/**
 * ZOK Specialty Seed — domain-specific Maßnahmen + Risiken for leaf ZOKs
 * that the family-routed catalog does not cover sufficiently. Seeds are
 * MERGED on top of the auto-generated `zokCatalog` by the resolver so that,
 * for example, a Webserver asset gets TLS/HSTS specifics in addition to the
 * inherited generic application measures.
 *
 * Design goals
 *  - Cover every leaf ZOK with at least 3-6 highly targeted controls.
 *  - Each measure carries a plausible ISO 27002:2022 + BSI Grundschutz++ ref.
 *  - DE/EN bilingual, no third language allowed.
 */

import type { CatalogMeasure, CatalogRisk } from "./controlCatalog";
import type { ZokId } from "./zielobjektkategorien";

export interface ZokSpecialtyEntry {
  measures: CatalogMeasure[];
  risks: CatalogRisk[];
}

const m = (
  id: string, title_de: string, title_en: string,
  description_de: string, description_en: string,
  iso_ref: string, bsi_ref: string,
  priority: "must" | "should" | "could" = "should",
  effort: "low" | "medium" | "high" = "medium",
): CatalogMeasure => ({
  id, title_de, title_en, description_de, description_en,
  iso_ref, bsi_ref, priority, effort,
});

const r = (
  id: string, title_de: string, title_en: string,
  description_de: string, description_en: string,
  threat_category: string, cia: ("C" | "I" | "A")[],
  typical_likelihood: number, typical_impact: number,
): CatalogRisk => ({
  id, title_de, title_en, description_de, description_en,
  threat_category, cia, typical_likelihood, typical_impact,
});

